mapper.select:
select wo.*, su.name suName, war.start_time startTime from wms_outbound wo left join wms_move_outbound_detail wod on wod.outbound_id = wo.id left join sys_user su on su.id = wo.applicant_id left join wms_approve_record war on war.id = wo.approve_record_id where wo.bool_delete_enum = 0 and wo.review_status = 2 and wo.outbound_type_selection = 16
and wo.contain_basic_class & #{basicClass} > 0
and wod.source_project_id = #{projectId}
and wo.serial_number like CONCAT('%', #{serialNumber},'%')
and su.name like CONCAT('%', #{operatorName},'%')
and wod.outbound_time >= #{outboundTime[0]}
and wod.outbound_time <= #{outboundTime[1]}
AND date_format(wod.outbound_time, '%Y-%m-%d') >= date_format(#{materialOutboundTime[0]}, '%Y-%m-%d')
AND date_format(wod.outbound_time, '%Y-%m-%d') <= date_format(#{materialOutboundTime[1]}, '%Y-%m-%d')
and wo.review_time >= #{reviewTime[0]}
and wo.review_time <= #{reviewTime[1]}
group by wo.id

select
*
from
wms_outbound
where
bool_delete_enum = 0
and bool_scheduling = 1

    and review_status = #{type}


    
        and create_time >= #{createTime[0]}
    
    
        and create_time <= #{createTime[1]}
    


    and mes_workshop_id = #{mesWorkshopId}

select wo.* from wms_outbound wo where wo.bool_delete_enum = 0 and wo.review_status = 2
and wo.contain_basic_class & #{ basicClass} > 0
and wo.bool_party_a = #{boolPartyA}
and wo.serial_number like CONCAT('%', #{serialNumber},'%')
and ( wo.applicant_name like CONCAT('%', #{operatorName},'%') or wo.reviewer_name like CONCAT('%', #{operatorName},'%'))
and wo.project_ids is null
and wo.project_ids IS NOT NULL
and find_in_set(#{projectId},wo.project_ids)
and wo.outbound_type_selection = #{outboundTypeSelection}
and wo.outbound_time >= #{outboundTime[0]}
and wo.outbound_time <= #{outboundTime[1]}
and wo.create_time >= #{createTime[0]}
and wo.create_time <= #{createTime[1]}
AND EXISTS( select 1 from wms_move_outbound_detail wmod where wmod.bool_delete_enum = FALSE and wmod.bool_party_a = 0 and wmod.outbound_id = wo.id )
AND EXISTS( select 1 from wms_move_outbound_detail wmod where wmod.bool_delete_enum = FALSE and wmod.bool_party_a = 1 and wmod.outbound_id = wo.id )

select * from wms_move_outbound_detail wmod left join wms_outbound wo on wmod.outbound_id = wo.id and wo.bool_delete_enum = 0 and wo.review_status = 2 where wmod.bool_delete_enum = 0
and wmod.basic_class & #{basicClass} > 0
and wmod.source_workshop_id = #{workshopId}
ORDER BY wmod.id DESC
limit #{size}
